// Normalize the inbound webhook payload into the canonical source-intake shape.
const body = items[0].json;
return [{
  json: {
    source_url: typeof body.source_url === 'string' ? body.source_url : '',
    source_title: typeof body.source_title === 'string' ? body.source_title : '',
    publisher: typeof body.publisher === 'string' ? body.publisher : '',
    published_at: typeof body.published_at === 'string' ? body.published_at : null,
    competition: typeof body.competition === 'string' ? body.competition : '',
    teams: Array.isArray(body.teams) ? body.teams : [],
    people: Array.isArray(body.people) ? body.people : [],
    source_text: typeof body.source_text === 'string' ? body.source_text : '',
    source_type: typeof body.source_type === 'string' ? body.source_type : 'other',
    requested_by: typeof body.requested_by === 'string' ? body.requested_by : 'anonymous',
    optional_metadata: typeof body.optional_metadata === 'object' && body.optional_metadata ? body.optional_metadata : {},
  },
}];

// Phase 18G — promote canonical envelope from FF90-01 output.
// FF90-01 now emits the canonical envelope (via Promote FF90-01 output
// Code node) instead of an Audit log response. We read it directly.
const result = $json;
const runId = result.run_id || null;
const editorialItemId = result.editorial_item_id || null;
// Stop the chain on terminal non-accepted states from FF90-01.
const stopStates = ['duplicate', 'failed'];
if (stopStates.includes(result.pipeline_status) || !editorialItemId) {
  return [{
    json: {
      ...result,
      status: 'duplicate_or_failed',
      run_id: runId,
      editorial_item_id: editorialItemId,
      pipeline_stage: result.pipeline_stage || 'source_intake',
      error_code: null,
      retryable: false,
      timestamp: new Date().toISOString(),
    },
  }];
}
return [{
  json: {
    ...result,
    status: 'accepted',
    run_id: runId,
    editorial_item_id: editorialItemId,
  },
}];

// Phase 18G — Final envelope. Re-emits canonical pipeline envelope
// with all FF90-04 + FF90-05 fields preserved. No wp-publish call.
// In manual_review mode this returns waiting_human_review.
return [{
  json: {
    ...$json,
    pipeline_stage: 'complete',
    pipeline_status: $json.pipeline_status || 'waiting_human_review',
    publish_mode: 'manual_review',
    auto_publish: false,
    timestamp: new Date().toISOString(),
  },
}];

// Duplicate / error early-out. The downstream stages are NOT executed.
return [{
  json: {
    status: $json.status,
    run_id: $json.run_id,
    editorial_item_id: $json.editorial_item_id,
    stage: 'source_intake',
    error_code: null,
    retryable: false,
    timestamp: new Date().toISOString(),
  },
}];

// Phase 18G — short-circuit when FF90-02 returned held_for_content
// (or any non-accepted pipeline_status from editorial factory).
// Do NOT proceed to image factory or WP draft.
return [{
  json: {
    ...$json,
    pipeline_stage: 'editorial_factory',
    pipeline_status: 'held_for_content',
    error_code: 'editorial_held_for_content',
    timestamp: new Date().toISOString(),
  },
}];
